CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_JS_FLATTEN_EVENTS()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS CALLER
AS $$
var stmt = snowflake.createStatement({sqlText: "INSERT INTO DW.FACT_CUSTOMER_ORDERS (order_id, customer_id, store_id, order_date, item_count, subtotal, discount, total, channel) SELECT e.payload:order_id::BIGINT, e.payload:customer_id::INT, e.payload:store_id::INT, e.payload:order_date::DATE, e.payload:item_count::INT, e.payload:subtotal::DECIMAL(14,2), e.payload:discount::DECIMAL(10,2), e.payload:total::DECIMAL(14,2), e.payload:channel::VARCHAR FROM STAGING.STG_JSON_EVENTS e WHERE e.event_type = 'ORDER' AND e.payload:order_id NOT IN (SELECT order_id FROM DW.FACT_CUSTOMER_ORDERS)"});
var result = stmt.execute();
var logStmt = snowflake.createStatement({sqlText: "CALL DW.SP_JS_ERROR_HANDLER('SP_JS_FLATTEN_EVENTS', 'SUCCESS', '')"});
logStmt.execute();
return 'Events flattened';
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_JS_MULTI_TABLE_SYNC()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS CALLER
AS $$
var tables = ['DIM_STORE', 'DIM_PRODUCT', 'DIM_CUSTOMER'];
var synced = 0;
for (var i = 0; i < tables.length; i++) {
  var tbl = tables[i];
  var sql = "INSERT INTO DW." + tbl + " SELECT * FROM STAGING.RAW_" + tbl.replace('DIM_', '') + "S";
  var stmt = snowflake.createStatement({sqlText: sql});
  stmt.execute();
  synced++;
}
return 'Synced ' + synced + ' tables';
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_JS_VALIDATE_SCHEMA()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS CALLER
AS $$
var listStmt = snowflake.createStatement({sqlText: "SELECT table_name, expected_columns FROM DW.SCHEMA_REGISTRY WHERE status = 'PENDING'"});
var rs = listStmt.execute();
var failures = [];
while (rs.next()) {
  var tbl = rs.getColumnValue(1);
  var expected = rs.getColumnValue(2);
  var updStmt = snowflake.createStatement({sqlText: "UPDATE DW.SCHEMA_REGISTRY SET status = 'VALID', last_validated = CURRENT_TIMESTAMP() WHERE table_name = '" + tbl + "'"});
  updStmt.execute();
}
return failures.length === 0 ? 'All schemas valid' : 'Drift: ' + failures.join(', ');
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_JS_GENERATE_REPORT("REPORT_NAME" VARCHAR)
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS CALLER
AS $$
var metrics = [
  {key: 'total_revenue', sql: "SELECT SUM(total_amount) FROM DW.FACT_SALES"},
  {key: 'total_orders', sql: "SELECT COUNT(*) FROM DW.FACT_CUSTOMER_ORDERS"},
  {key: 'active_stores', sql: "SELECT COUNT(*) FROM DW.DIM_STORE WHERE close_date IS NULL"}
];
for (var i = 0; i < metrics.length; i++) {
  var m = metrics[i];
  var valStmt = snowflake.createStatement({sqlText: m.sql});
  var rs = valStmt.execute();
  rs.next();
  var val = rs.getColumnValue(1);
  var insStmt = snowflake.createStatement({sqlText: "INSERT INTO DW.REPORT_OUTPUT (report_name, metric_key, metric_value, report_date) VALUES ('" + REPORT_NAME + "', '" + m.key + "', " + val + ", CURRENT_DATE())"});
  insStmt.execute();
}
return 'Report generated';
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_JS_SCD_TYPE2()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS CALLER
AS $$
// Close existing records that have changed
var closeStmt = snowflake.createStatement({sqlText: "UPDATE DW.DIM_CUSTOMER SET is_current = FALSE, valid_to = CURRENT_TIMESTAMP() WHERE customer_id IN (SELECT c.customer_id FROM DW.DIM_CUSTOMER c JOIN STAGING.RAW_CUSTOMERS r ON c.customer_id = r.customer_id WHERE c.is_current = TRUE AND (c.loyalty_tier != r.loyalty_tier OR c.email != r.email))"});
closeStmt.execute();
var insertStmt = snowflake.createStatement({sqlText: "INSERT INTO DW.DIM_CUSTOMER (customer_id, first_name, last_name, email, loyalty_tier, signup_date, is_current, valid_from) SELECT r.customer_id, r.first_name, r.last_name, r.email, r.loyalty_tier, r.signup_date, TRUE, CURRENT_TIMESTAMP() FROM STAGING.RAW_CUSTOMERS r WHERE NOT EXISTS (SELECT 1 FROM DW.DIM_CUSTOMER c WHERE c.customer_id = r.customer_id AND c.is_current = TRUE AND c.loyalty_tier = r.loyalty_tier AND c.email = r.email)"});
insertStmt.execute();
return 'SCD Type 2 applied';
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_JS_ERROR_HANDLER("PROC_NAME" VARCHAR, "STATUS" VARCHAR, "ERROR_MSG" VARCHAR)
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS CALLER
AS $$
var stmt = snowflake.createStatement({sqlText: "INSERT INTO DW.ETL_LOG (log_message, log_timestamp, log_level) VALUES ('" + PROC_NAME + ": " + STATUS + "', CURRENT_TIMESTAMP(), '" + (STATUS === 'SUCCESS' ? 'INFO' : 'ERROR') + "')"});
stmt.execute();
return STATUS;
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_JS_PARTITION_CLEANUP("RETENTION_DAYS" NUMBER)
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS CALLER
AS $$
var cutoff = "DATEADD(DAY, -" + RETENTION_DAYS + ", CURRENT_DATE())";
var delStmt = snowflake.createStatement({sqlText: "DELETE FROM DW.FACT_SALES WHERE date_key IN (SELECT date_key FROM DW.DIM_DATE WHERE day_date < " + cutoff + ")"});
var result = delStmt.execute();
result.next();
var removed = result.getColumnValue(1);
var logStmt = snowflake.createStatement({sqlText: "INSERT INTO DW.PARTITION_LOG (table_name, partition_key, rows_removed) VALUES ('FACT_SALES', 'date_key', " + removed + ")"});
logStmt.execute();
return 'Removed ' + removed + ' rows';
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_JS_ORCHESTRATE_EVENTS()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS CALLER
AS $$
var step1 = snowflake.createStatement({sqlText: "CALL DW.SP_JS_FLATTEN_EVENTS()"});
step1.execute();
var step2 = snowflake.createStatement({sqlText: "CALL DW.SP_JS_VALIDATE_SCHEMA()"});
step2.execute();
var step3 = snowflake.createStatement({sqlText: "CALL DW.SP_JS_SCD_TYPE2()"});
step3.execute();
var step4 = snowflake.createStatement({sqlText: "CALL DW.SP_JS_ERROR_HANDLER('SP_JS_ORCHESTRATE_EVENTS', 'SUCCESS', '')"});
step4.execute();
return 'Event pipeline complete';
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_SCRIPTING_RETRY_LOADER("MAX_RETRIES" INT)
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
DECLARE
  attempt INT DEFAULT 0;
  row_count INT DEFAULT 0;
  rs RESULTSET;
BEGIN
  WHILE (attempt < :MAX_RETRIES AND row_count = 0) DO
    LET attempt := attempt + 1;
    INSERT INTO DW.FACT_CUSTOMER_ORDERS (order_id, customer_id, store_id, order_date, item_count, subtotal, discount, total, channel)
    SELECT e.payload:order_id::BIGINT, e.payload:customer_id::INT, e.payload:store_id::INT,
           e.payload:order_date::DATE, e.payload:item_count::INT, e.payload:subtotal::DECIMAL(14,2),
           e.payload:discount::DECIMAL(10,2), e.payload:total::DECIMAL(14,2), e.payload:channel::VARCHAR
    FROM STAGING.STG_JSON_EVENTS e
    WHERE e.event_type = 'ORDER'
      AND e.payload:order_id NOT IN (SELECT order_id FROM DW.FACT_CUSTOMER_ORDERS);
    rs := (SELECT COUNT(*) AS cnt FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
    LET row_count := (SELECT cnt FROM TABLE(rs));
  END WHILE;
  CALL DW.SP_LOG_ETL_STATUS('Retry loader: ' || attempt || ' attempts, ' || row_count || ' rows');
  RETURN 'Loaded ' || row_count || ' rows in ' || attempt || ' attempts';
END;
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_SCRIPTING_CONDITIONAL_LOAD("TARGET_TABLE" VARCHAR)
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
DECLARE
  stg_count INT;
  load_sql VARCHAR;
BEGIN
  SELECT COUNT(*) INTO :stg_count FROM STAGING.RAW_TRANSACTIONS WHERE loaded_at > DATEADD(HOUR, -1, CURRENT_TIMESTAMP());
  IF (stg_count > 0) THEN
    load_sql := 'INSERT INTO DW.' || :TARGET_TABLE || ' SELECT * FROM STAGING.RAW_TRANSACTIONS WHERE loaded_at > DATEADD(HOUR, -1, CURRENT_TIMESTAMP())';
    EXECUTE IMMEDIATE :load_sql;
    CALL DW.SP_LOG_ETL_STATUS('Conditional load: ' || stg_count || ' rows into ' || :TARGET_TABLE);
  ELSE
    CALL DW.SP_LOG_ETL_STATUS('Conditional load: no new data for ' || :TARGET_TABLE);
  END IF;
  RETURN 'Done';
END;
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_SCRIPTING_CURSOR_PROCESS()
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
DECLARE
  c1 CURSOR FOR SELECT product_id, product_name FROM DW.DIM_PRODUCT WHERE is_active = TRUE;
  pid INT;
  pname VARCHAR;
  processed INT DEFAULT 0;
BEGIN
  FOR row IN c1 DO
    pid := row.product_id;
    pname := row.product_name;
    UPDATE DW.DIM_PRODUCT SET etl_updated_at = CURRENT_TIMESTAMP() WHERE product_id = :pid;
    LET processed := processed + 1;
  END FOR;
  CALL DW.SP_LOG_ETL_STATUS('Cursor process: updated ' || processed || ' products');
  RETURN 'Processed ' || processed || ' products';
END;
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_MASTER_PIPELINE()
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
CALL DW.SP_RUN_NIGHTLY_ETL();
CALL DW.SP_JS_ORCHESTRATE_EVENTS();
CALL DW.SP_JS_MULTI_TABLE_SYNC();
CALL DW.SP_SCRIPTING_CONDITIONAL_LOAD('FACT_SALES');
CALL DW.SP_JS_GENERATE_REPORT('DAILY_SUMMARY');
CALL DW.SP_LOG_ETL_STATUS('Master pipeline complete');
$$;
